import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 79 Carol's shopping list","description":"学习 need 与 must，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 79 Carol's shopping list","description":"学习 need 与 must，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 need 与 must，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 78 When did you ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-078"},"next":{"text":"第一册：英语初阶 · Lesson 80 I must go to the ...","link":"/life/english/new-concept/book-1/unit-04/lesson-080"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 78 When did you ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-078"},"next":{"text":"第一册：英语初阶 · Lesson 80 I must go to the ...","link":"/life/english/new-concept/book-1/unit-04/lesson-080"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/lesson-079.md","filePath":"life/english/new-concept/book-1/unit-04/lesson-079.md"}`),s={name:"life/english/new-concept/book-1/unit-04/lesson-079.md"};function i(l,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-79-carol-s-shopping-list" tabindex="-1">第一册：英语初阶 · Lesson 79 Carol&#39;s shopping list <a class="header-anchor" href="#第一册-英语初阶-·-lesson-79-carol-s-shopping-list" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 79 Carol&#39;s shopping list&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元 4</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-080">配套课 Lesson 80</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>根据购物清单表达需要去哪里 本课要掌握need 与 must，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>list</td><td>/lɪst/</td><td>n.</td><td>清单</td><td>a shopping list</td></tr><tr><td>grocer</td><td>/ˈɡrəʊsə/</td><td>n.</td><td>食品杂货商</td><td>at the grocer&#39;s</td></tr><tr><td>vegetable</td><td>/ˈvedʒtəbl/</td><td>n.</td><td>蔬菜</td><td>fresh vegetables</td></tr><tr><td>need</td><td>/niːd/</td><td>v.</td><td>需要</td><td>need to shop</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>need to buy — 需要购买</li><li>must go — 必须去，不加 to</li></ul><h2 id="语法讲解-need-与-must" tabindex="-1">语法讲解：need 与 must <a class="header-anchor" href="#语法讲解-need-与-must" aria-label="Permalink to &quot;语法讲解：need 与 must&quot;">​</a></h2><p>need 作实义动词时，可接名词或 to do：need some rice、need to buy rice。第三人称用 needs，否定借助 don&#39;t/doesn&#39;t。must 是情态动词，直接加原形，不加 to。needn&#39;t 是“不必”，其后直接接动词原形。学习时先确定用的是实义动词 need 还是情态表达，避免混用句式。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We need to buy rice and tomatoes.</p></blockquote><p>我们需要买米和西红柿。</p><p>Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>need to go 与 must go 的结构不同；不要写 must to go。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“We need to buy rice and tomatoes.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We need to buy rice and tomatoes. She must go to the pharmacy before six.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“根据购物清单表达需要去哪里”写两至三句，再读给同伴听。至少使用一次need 与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。 She 为主语，must 后直接接 go；to the pharmacy 表目的地，before six 表时间界限。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填小词：We need ___ buy rice.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> 按本课规则判断：need 作实义动词时，可接名词或 to do：need some rice、need to buy rice。第三人称用 needs，否定借助 don&#39;t/doesn&#39;t。must 是情态动词，直接加原形，不加 to。needn&#39;t 是“不必”，其后直接接动词原形。学习时先确定用的是实义动词 need 还是情态表达，避免混用句式。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我们需要买米和西红柿。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We need to buy rice and tomatoes.</p><p><strong>解析：</strong> Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：She must go to the pharmacy before six.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 她必须六点前去药店。</p><p><strong>解析：</strong> She 为主语，must 后直接接 go；to the pharmacy 表目的地，before six 表时间界限。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：need 与 must。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-078">上一课</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-080">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(s,[["render",i]]);export{p as __pageData,b as default};
